import{_ as t,o,c as a,aj as i}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"Angular compiler options","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"reference/configs/angular-compiler-options.md","filePath":"reference/configs/angular-compiler-options.md"}'),s={name:"reference/configs/angular-compiler-options.md"};function n(r,e,l,c,d,p){return o(),a("div",null,e[0]||(e[0]=[i('<h1 id="angular-compiler-options" tabindex="-1">Angular compiler options <a class="header-anchor" href="#angular-compiler-options" aria-label="Permalink to &quot;Angular compiler options&quot;">​</a></h1><p>When you use <a href="/tools/cli/aot-compiler">ahead-of-time compilation (AOT)</a>, you can control how your application is compiled by specifying Angular compiler options in the <a href="https://www.typescriptlang.org/docs/handbook/tsconfig-json.html" target="_blank" rel="noreferrer">TypeScript configuration file</a>.</p><p>The Angular options object, <code>angularCompilerOptions</code>, is a sibling to the <code>compilerOptions</code> object that supplies standard options to the TypeScript compiler.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;compileOnSave&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;compilerOptions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;angularCompilerOptions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;enableI18nLegacyMessageIdFormat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;strictInjectionParameters&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="configuration-inheritance-with-extends" tabindex="-1">Configuration inheritance with <code>extends</code> <a class="header-anchor" href="#configuration-inheritance-with-extends" aria-label="Permalink to &quot;Configuration inheritance with `extends`&quot;">​</a></h2><p>Like the TypeScript compiler, the Angular AOT compiler also supports <code>extends</code> in the <code>angularCompilerOptions</code> section of the TypeScript configuration file. The <code>extends</code> property is at the top level, parallel to <code>compilerOptions</code> and <code>angularCompilerOptions</code>.</p><p>A TypeScript configuration can inherit settings from another file using the <code>extends</code> property. The configuration options from the base file are loaded first, then overridden by those in the inheriting configuration file.</p><p>For example:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;extends&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./tsconfig.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;compilerOptions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;outDir&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./out-tsc/app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;angularCompilerOptions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;preserveWhitespaces&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>For more information, see the <a href="https://www.typescriptlang.org/docs/handbook/tsconfig-json.html" target="_blank" rel="noreferrer">TypeScript Handbook</a>.</p><h2 id="template-options" tabindex="-1">Template options <a class="header-anchor" href="#template-options" aria-label="Permalink to &quot;Template options&quot;">​</a></h2><p>The following options are available for configuring the Angular AOT compiler.</p><h3 id="annotationsas" tabindex="-1"><code>annotationsAs</code> <a class="header-anchor" href="#annotationsas" aria-label="Permalink to &quot;`annotationsAs`&quot;">​</a></h3><p>Modifies how Angular-specific annotations are emitted to improve tree-shaking. Non-Angular annotations are not affected. One of <code>static fields</code> or <code>decorators</code>. The default value is <code>static fields</code>.</p><ul><li><p>By default, the compiler replaces decorators with a static field in the class, which allows advanced tree-shakers like <a href="https://github.com/google/closure-compiler" target="_blank" rel="noreferrer">Closure compiler</a> to remove unused classes</p></li><li><p>The <code>decorators</code> value leaves the decorators in place, which makes compilation faster. TypeScript emits calls to the <code>__decorate</code> helper. Use <code>--emitDecoratorMetadata</code> for runtime reflection.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>That the resulting code cannot tree-shake properly.</p></div></li></ul><h3 id="annotateforclosurecompiler" tabindex="-1"><code>annotateForClosureCompiler</code> <a class="header-anchor" href="#annotateforclosurecompiler" aria-label="Permalink to &quot;`annotateForClosureCompiler`&quot;">​</a></h3><p>When <code>true</code>, use <a href="https://github.com/angular/tsickle" target="_blank" rel="noreferrer">Tsickle</a> to annotate the emitted JavaScript with <a href="https://jsdoc.app" target="_blank" rel="noreferrer">JSDoc</a> comments needed by the <a href="https://github.com/google/closure-compiler" target="_blank" rel="noreferrer">Closure Compiler</a>. Default is <code>false</code>.</p><h3 id="compilationmode" tabindex="-1"><code>compilationMode</code> <a class="header-anchor" href="#compilationmode" aria-label="Permalink to &quot;`compilationMode`&quot;">​</a></h3><p>Specifies the compilation mode to use. The following modes are available:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Modes</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&#39;full&#39;</code></td><td style="text-align:left;">Generates fully AOT-compiled code. The compiler ABI (the internal runtime APIs used by this code) is stable across patch versions of the same minor version.</td></tr><tr><td style="text-align:left;"><code>&#39;partial&#39;</code></td><td style="text-align:left;">Generates code in a stable, but intermediate form suitable for independently published libraries.</td></tr></tbody></table><p>The default value is <code>&#39;full&#39;</code>.</p><p>For most applications, <code>&#39;full&#39;</code> is the correct compilation mode.</p><p>Use <code>&#39;partial&#39;</code> for independently published libraries, such as NPM packages. <code>&#39;partial&#39;</code> compilations output a stable, intermediate format which better supports usage by applications built at different major or minor Angular versions from the library. Libraries built at &quot;HEAD&quot; alongside their applications and using the same version of Angular such as in a mono-repository can use <code>&#39;full&#39;</code> since there is no risk of version skew across minor versions. Note that the compiler ABI is stable across patch versions of the same minor, allowing for safe sharing of the Angular runtime in microfrontend architectures where different applications might be on different patch levels.</p><h3 id="disabletypescriptversioncheck" tabindex="-1"><code>disableTypeScriptVersionCheck</code> <a class="header-anchor" href="#disabletypescriptversioncheck" aria-label="Permalink to &quot;`disableTypeScriptVersionCheck`&quot;">​</a></h3><p>When <code>true</code>, the compiler does not look at the TypeScript version and does not report an error when an unsupported version of TypeScript is used. Not recommended, as unsupported versions of TypeScript might have undefined behavior. Default is <code>false</code>.</p><h3 id="enablei18nlegacymessageidformat" tabindex="-1"><code>enableI18nLegacyMessageIdFormat</code> <a class="header-anchor" href="#enablei18nlegacymessageidformat" aria-label="Permalink to &quot;`enableI18nLegacyMessageIdFormat`&quot;">​</a></h3><p>Instructs the Angular template compiler to create legacy ids for messages that are tagged in templates by the <code>i18n</code> attribute. See <a href="./guide/i18n/prepare#mark-text-in-component-template" title="Mark text in component template - Prepare component for translation | Angular">Mark text for translations</a> for more information about marking messages for localization.</p><p>Set this option to <code>false</code> unless your project relies upon translations that were created earlier using legacy IDs. Default is <code>true</code>.</p><p>The pre-Ivy message extraction tooling created a variety of legacy formats for extracted message IDs. These message formats have some issues, such as whitespace handling and reliance upon information inside the original HTML of a template.</p><p>The new message format is more resilient to whitespace changes, is the same across all translation file formats, and can be created directly from calls to <code>$localize</code>. This allows <code>$localize</code> messages in application code to use the same ID as identical <code>i18n</code> messages in component templates.</p><div class="warning custom-block"><p class="custom-block-title">IMPORTANT</p><p>This option is only supported by the <code>@angular-devkit/build-angular:browser</code> builder. When using the <code>@angular/build:application</code> builder (esbuild), this option has no effect and the new decimal message ID format is always used regardless of this setting.</p></div><h3 id="enableresourceinlining" tabindex="-1"><code>enableResourceInlining</code> <a class="header-anchor" href="#enableresourceinlining" aria-label="Permalink to &quot;`enableResourceInlining`&quot;">​</a></h3><p>When <code>true</code>, replaces the <code>templateUrl</code> and <code>styleUrls</code> properties in all <code>@Component</code> decorators with inline content in the <code>template</code> and <code>styles</code> properties.</p><p>When enabled, the <code>.js</code> output of <code>ngc</code> does not include any lazy-loaded template or style URLs.</p><h3 id="flatmoduleid" tabindex="-1"><code>flatModuleId</code> <a class="header-anchor" href="#flatmoduleid" aria-label="Permalink to &quot;`flatModuleId`&quot;">​</a></h3><p>The module ID to use for importing a flat module (when <code>flatModuleOutFile</code> is <code>true</code>). References created by the template compiler use this module name when importing symbols from the flat module. Ignored if <code>flatModuleOutFile</code> is <code>false</code>.</p><h3 id="flatmoduleoutfile" tabindex="-1"><code>flatModuleOutFile</code> <a class="header-anchor" href="#flatmoduleoutfile" aria-label="Permalink to &quot;`flatModuleOutFile`&quot;">​</a></h3><p>When <code>true</code>, generates a flat module index of the given filename and the corresponding flat module metadata. Use to create flat modules that are packaged similarly to <code>@angular/core</code> and <code>@angular/common</code>. When this option is used, the <code>package.json</code> for the library should refer to the created flat module index instead of the library index file.</p><p>Produces only one <code>.metadata.json</code> file, which contains all the metadata necessary for symbols exported from the library index. In the created <code>.ngfactory.js</code> files, the flat module index is used to import symbols. Symbols that include both the public API from the library index and shrouded internal symbols.</p><p>By default, the <code>.ts</code> file supplied in the <code>files</code> field is assumed to be the library index. If more than one <code>.ts</code> file is specified, <code>libraryIndex</code> is used to select the file to use. If more than one <code>.ts</code> file is supplied without a <code>libraryIndex</code>, an error is produced.</p><p>A flat module index <code>.d.ts</code> and <code>.js</code> is created with the given <code>flatModuleOutFile</code> name in the same location as the library index <code>.d.ts</code> file.</p><p>For example, if a library uses the <code>public_api.ts</code> file as the library index of the module, the <code>tsconfig.json</code> <code>files</code> field would be <code>[&quot;public_api.ts&quot;]</code>. The <code>flatModuleOutFile</code> option could then be set, for example, to <code>&quot;index.js&quot;</code>, which produces <code>index.d.ts</code> and <code>index.metadata.json</code> files. The <code>module</code> field of the library&#39;s <code>package.json</code> would be <code>&quot;index.js&quot;</code> and the <code>typings</code> field would be <code>&quot;index.d.ts&quot;</code>.</p><h3 id="generatecodeforlibraries" tabindex="-1"><code>generateCodeForLibraries</code> <a class="header-anchor" href="#generatecodeforlibraries" aria-label="Permalink to &quot;`generateCodeForLibraries`&quot;">​</a></h3><p>When <code>true</code>, creates factory files (<code>.ngfactory.js</code> and <code>.ngstyle.js</code>) for <code>.d.ts</code> files with a corresponding <code>.metadata.json</code> file. The default value is <code>true</code>.</p><p>When <code>false</code>, factory files are created only for <code>.ts</code> files. Do this when using factory summaries.</p><h3 id="preservewhitespaces" tabindex="-1"><code>preserveWhitespaces</code> <a class="header-anchor" href="#preservewhitespaces" aria-label="Permalink to &quot;`preserveWhitespaces`&quot;">​</a></h3><p>When <code>false</code>, the default, removes blank text nodes from compiled templates, which results in smaller emitted template factory modules. Set to <code>true</code> to preserve blank text nodes.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>When using hydration, it is recommended that you use <code>preserveWhitespaces: false</code>, which is the default value. If you choose to enable preserving whitespaces by adding <code>preserveWhitespaces: true</code> to your tsconfig, it is possible you may encounter issues with hydration. This is not yet a fully supported configuration. Ensure this is also consistently set between the server and client tsconfig files. See the <a href="/guide/hydration#preserve-whitespaces-configuration">hydration guide</a> for more details.</p></div><h3 id="skipmetadataemit" tabindex="-1"><code>skipMetadataEmit</code> <a class="header-anchor" href="#skipmetadataemit" aria-label="Permalink to &quot;`skipMetadataEmit`&quot;">​</a></h3><p>When <code>true</code>, does not produce <code>.metadata.json</code> files. Default is <code>false</code>.</p><p>The <code>.metadata.json</code> files contain information needed by the template compiler from a <code>.ts</code> file that is not included in the <code>.d.ts</code> file produced by the TypeScript compiler. This information includes, for example, the content of annotations, such as a component&#39;s template, which TypeScript emits to the <code>.js</code> file but not to the <code>.d.ts</code> file.</p><p>You can set to <code>true</code> when using factory summaries, because the factory summaries include a copy of the information that is in the <code>.metadata.json</code> file.</p><p>Set to <code>true</code> if you are using TypeScript&#39;s <code>--outFile</code> option, because the metadata files are not valid for this style of TypeScript output. The Angular community does not recommend using <code>--outFile</code> with Angular. Use a bundler, such as <a href="https://webpack.js.org" target="_blank" rel="noreferrer">webpack</a>, instead.</p><h3 id="skiptemplatecodegen" tabindex="-1"><code>skipTemplateCodegen</code> <a class="header-anchor" href="#skiptemplatecodegen" aria-label="Permalink to &quot;`skipTemplateCodegen`&quot;">​</a></h3><p>When <code>true</code>, does not emit <code>.ngfactory.js</code> and <code>.ngstyle.js</code> files. This turns off most of the template compiler and disables the reporting of template diagnostics.</p><p>Can be used to instruct the template compiler to produce <code>.metadata.json</code> files for distribution with an <code>npm</code> package. This avoids the production of <code>.ngfactory.js</code> and <code>.ngstyle.js</code> files that cannot be distributed to <code>npm</code>.</p><h3 id="strictmetadataemit" tabindex="-1"><code>strictMetadataEmit</code> <a class="header-anchor" href="#strictmetadataemit" aria-label="Permalink to &quot;`strictMetadataEmit`&quot;">​</a></h3><p>When <code>true</code>, reports an error to the <code>.metadata.json</code> file if <code>&quot;skipMetadataEmit&quot;</code> is <code>false</code>. Default is <code>false</code>. Use only when <code>&quot;skipMetadataEmit&quot;</code> is <code>false</code> and <code>&quot;skipTemplateCodegen&quot;</code> is <code>true</code>.</p><p>This option is intended to verify the <code>.metadata.json</code> files emitted for bundling with an <code>npm</code> package. The validation is strict and can emit errors for metadata that would never produce an error when used by the template compiler. You can choose to suppress the error emitted by this option for an exported symbol by including <code>@dynamic</code> in the comment documenting the symbol.</p><p>It is valid for <code>.metadata.json</code> files to contain errors. The template compiler reports these errors if the metadata is used to determine the contents of an annotation. The metadata collector cannot predict the symbols that are designed for use in an annotation. It preemptively includes error nodes in the metadata for the exported symbols. The template compiler can then use the error nodes to report an error if these symbols are used.</p><p>If the client of a library intends to use a symbol in an annotation, the template compiler does not normally report this. It gets reported after the client actually uses the symbol. This option allows detection of these errors during the build phase of the library and is used, for example, in producing Angular libraries themselves.</p><h3 id="strictinjectionparameters" tabindex="-1"><code>strictInjectionParameters</code> <a class="header-anchor" href="#strictinjectionparameters" aria-label="Permalink to &quot;`strictInjectionParameters`&quot;">​</a></h3><p>When <code>true</code>, reports an error for a supplied parameter whose injection type cannot be determined. When <code>false</code>, constructor parameters of classes marked with <code>@Injectable</code> whose type cannot be resolved produce a warning. The recommended value is <code>true</code>, but the default value is <code>false</code>.</p><p>When you use the Angular CLI command <code>ng new --strict</code>, it is set to <code>true</code> in the created project&#39;s configuration.</p><h3 id="stricttemplates" tabindex="-1"><code>strictTemplates</code> <a class="header-anchor" href="#stricttemplates" aria-label="Permalink to &quot;`strictTemplates`&quot;">​</a></h3><p>When <code>true</code>, enables <a href="/tools/cli/template-typecheck#strict-mode">strict template type checking</a>.</p><p>The strictness flags that this option enables allow you to turn on and off specific types of strict template type checking. See <a href="/tools/cli/template-typecheck#troubleshooting-template-errors">troubleshooting template errors</a>. Default is <code>true</code>.</p><h3 id="strictstandalone" tabindex="-1"><code>strictStandalone</code> <a class="header-anchor" href="#strictstandalone" aria-label="Permalink to &quot;`strictStandalone`&quot;">​</a></h3><p>When <code>true</code>, reports an error if a component, directive, or pipe is not standalone.</p><h3 id="trace" tabindex="-1"><code>trace</code> <a class="header-anchor" href="#trace" aria-label="Permalink to &quot;`trace`&quot;">​</a></h3><p>When <code>true</code>, prints extra information while compiling templates. Default is <code>false</code>.</p><h3 id="typecheckhostbindings" tabindex="-1"><code>typeCheckHostBindings</code> <a class="header-anchor" href="#typecheckhostbindings" aria-label="Permalink to &quot;`typeCheckHostBindings`&quot;">​</a></h3><p>When <code>true</code>, enables type checking of expressions in the <code>host</code> object literal and <code>@HostBinding</code>/<code>@HostListener</code> decorators of components and directives. Default is <code>true</code>.</p><h2 id="command-line-options" tabindex="-1">Command line options <a class="header-anchor" href="#command-line-options" aria-label="Permalink to &quot;Command line options&quot;">​</a></h2><p>Most of the time, you interact with the Angular Compiler indirectly using <a href="/reference/configs/angular-compiler-options">Angular CLI</a>. When debugging certain issues, you might find it useful to invoke the Angular Compiler directly. You can use the <code>ngc</code> command provided by the <code>@angular/compiler-cli</code> npm package to call the compiler from the command line.</p><p>The <code>ngc</code> command is a wrapper around TypeScript&#39;s <code>tsc</code> compiler command. The Angular Compiler is primarily configured through <code>tsconfig.json</code> while Angular CLI is primarily configured through <code>angular.json</code>.</p><p>Besides the configuration file, you can also use <a href="https://www.typescriptlang.org/docs/handbook/compiler-options.html" target="_blank" rel="noreferrer"><code>tsc</code> command line options</a> to configure <code>ngc</code>.</p>',77)]))}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
